package app

import "fyne.io/fyne/v2"

var appMeta fyne.AppMetadata

// SetMetadata sets the application metadata that will be returned by Metadata() calls.
// This should be called before creating the app, typically in an init() function or
// at the start of main().
//
// Since: 2.5
func SetMetadata(m fyne.AppMetadata) {
	appMeta = m
}

func (a *fyneApp) setMetadataDefaults() {
	if appMeta.ID != "" {
		a.meta = appMeta
	}
}

package app

import "fyne.io/fyne/v2"

var appMeta fyne.AppMetadata

// SetMetadata sets the application metadata that will be returned by Metadata() calls.
// This should be called before creating the app, typically in an init() function or
// at the start of main().
//
// Since: 2.5
func SetMetadata(m fyne.AppMetadata) {
