// jsonTheme wraps a theme with JSON-defined overrides
type jsonTheme struct {
	colors      map[fyne.ThemeColorName]color.Color
	colorsDark  map[fyne.ThemeColorName]color.Color
	colorsLight map[fyne.ThemeColorName]color.Color
	sizes       map[fyne.ThemeSizeName]float32
	fonts       map[fyne.TextStyle]fyne.Resource
	icons       map[fyne.ThemeIconName]fyne.Resource
	fallback    fyne.Theme
}

// jsonThemeData represents the JSON structure for theme definition
type jsonThemeData struct {
	Colors      map[string]string  `json:"Colors"`
	ColorsDark  map[string]string  `json:"Colors-dark"`
	ColorsLight map[string]string  `json:"Colors-light"`
	Sizes       map[string]float32 `json:"Sizes"`
	Fonts       map[string]string  `json:"Fonts"`
	Icons       map[string]string  `json:"Icons"`
}

// Color returns the color for the given name and variant
func (t *jsonTheme) Color(name fyne.ThemeColorName, variant fyne.ThemeVariant) color.Color {
	// Check variant-specific colors first
	if variant == VariantDark && t.colorsDark != nil {
		if c, ok := t.colorsDark[name]; ok {
			return c
		}
	}
	if variant == VariantLight && t.colorsLight != nil {
		if c, ok := t.colorsLight[name]; ok {
			return c
		}
	}

	// Check generic colors
	if t.colors != nil {
		if c, ok := t.colors[name]; ok {
			return c
		}
	}

	// Fall back to default theme
	return t.fallback.Color(name, variant)
}

// Font returns the font resource for the given text style
func (t *jsonTheme) Font(style fyne.TextStyle) fyne.Resource {
	if t.fonts != nil {
		if f, ok := t.fonts[style]; ok {
			return f
		}
	}
	return t.fallback.Font(style)
}

// Icon returns the icon resource for the given name
func (t *jsonTheme) Icon(name fyne.ThemeIconName) fyne.Resource {
	if t.icons != nil {
		if i, ok := t.icons[name]; ok {
			return i
		}
	}
	return t.fallback.Icon(name)
}

// Size returns the size for the given name
func (t *jsonTheme) Size(name fyne.ThemeSizeName) float32 {
	if t.sizes != nil {
		if s, ok := t.sizes[name]; ok {
			return s
		}
	}
	return t.fallback.Size(name)
}

// parseHexColor parses a hex color string and returns a color.Color
// Supports formats: #rgb, #rgba, #rrggbb, #rrggbbaa (# is optional)
func parseHexColor(hexStr string) (color.Color, error) {
	hexStr = strings.TrimPrefix(hexStr, "#")

	var r, g, b, a uint8 = 0, 0, 0, 255

	switch len(hexStr) {
	case 3: // rgb
		rv, _ := strconv.ParseUint(hexStr[0:1], 16, 8)
		gv, _ := strconv.ParseUint(hexStr[1:2], 16, 8)
		bv, _ := strconv.ParseUint(hexStr[2:3], 16, 8)
		r, g, b = uint8(rv*17), uint8(gv*17), uint8(bv*17)
	case 4: // rgba
		rv, _ := strconv.ParseUint(hexStr[0:1], 16, 8)
		gv, _ := strconv.ParseUint(hexStr[1:2], 16, 8)
		bv, _ := strconv.ParseUint(hexStr[2:3], 16, 8)
		av, _ := strconv.ParseUint(hexStr[3:4], 16, 8)
		r, g, b, a = uint8(rv*17), uint8(gv*17), uint8(bv*17), uint8(av*17)
	case 6: // rrggbb
		rv, _ := strconv.ParseUint(hexStr[0:2], 16, 8)
		gv, _ := strconv.ParseUint(hexStr[2:4], 16, 8)
		bv, _ := strconv.ParseUint(hexStr[4:6], 16, 8)
		r, g, b = uint8(rv), uint8(gv), uint8(bv)
	case 8: // rrggbbaa
		rv, _ := strconv.ParseUint(hexStr[0:2], 16, 8)
		gv, _ := strconv.ParseUint(hexStr[2:4], 16, 8)
		bv, _ := strconv.ParseUint(hexStr[4:6], 16, 8)
		av, _ := strconv.ParseUint(hexStr[6:8], 16, 8)
		r, g, b, a = uint8(rv), uint8(gv), uint8(bv), uint8(av)
	default:
		return color.NRGBA{0, 0, 0, 0}, fmt.Errorf("invalid hex color format: %s", hexStr)
	}

	return color.NRGBA{R: r, G: g, B: b, A: a}, nil
}

// parseColors parses a map of color names to hex strings
func parseColors(colorMap map[string]string) (map[fyne.ThemeColorName]color.Color, error) {
	if colorMap == nil {
		return nil, nil
	}

	result := make(map[fyne.ThemeColorName]color.Color)
	for name, hexStr := range colorMap {
		c, err := parseHexColor(hexStr)
		if err != nil {
			return nil, fmt.Errorf("error parsing color %s: %w", name, err)
		}
		result[fyne.ThemeColorName(name)] = c
	}
	return result, nil
}

// parseFonts parses a map of font style names to URIs
func parseFonts(fontMap map[string]string) (map[fyne.TextStyle]fyne.Resource, error) {
	if fontMap == nil {
		return nil, nil
	}

	result := make(map[fyne.TextStyle]fyne.Resource)
	styleMap := map[string]fyne.TextStyle{
		"regular":    {},
		"bold":       {Bold: true},
		"italic":     {Italic: true},
		"bolditalic": {Bold: true, Italic: true},
		"monospace":  {Monospace: true},
	}

	for styleName, uriStr := range fontMap {
		style, ok := styleMap[strings.ToLower(styleName)]
		if !ok {
			return nil, fmt.Errorf("unknown font style: %s", styleName)
		}

		uri, err := storage.ParseURI(uriStr)
		if err != nil {
			return nil, fmt.Errorf("error parsing font URI %s: %w", uriStr, err)
		}

		res, err := storage.LoadResourceFromURI(uri)
		if err != nil {
			return nil, fmt.Errorf("error loading font resource %s: %w", uriStr, err)
		}

		result[style] = res
	}
	return result, nil
}

// parseIcons parses a map of icon names to URIs
func parseIcons(iconMap map[string]string) (map[fyne.ThemeIconName]fyne.Resource, error) {
	if iconMap == nil {
		return nil, nil
	}

	result := make(map[fyne.ThemeIconName]fyne.Resource)
	for name, uriStr := range iconMap {
		uri, err := storage.ParseURI(uriStr)
		if err != nil {
			return nil, fmt.Errorf("error parsing icon URI %s: %w", uriStr, err)
		}

		res, err := storage.LoadResourceFromURI(uri)
		if err != nil {
			return nil, fmt.Errorf("error loading icon resource %s: %w", uriStr, err)
		}

		result[fyne.ThemeIconName(name)] = res
	}
	return result, nil
}

// FromJSON parses a JSON string and returns a Theme.
// On parse error, returns the default theme along with the error.
//
// Since: 2.5
func FromJSON(data string) (fyne.Theme, error) {
	return FromJSONReader(strings.NewReader(data))
}

// FromJSONReader parses JSON from an io.Reader and returns a Theme.
// On parse error, returns the default theme along with the error.
//
// Since: 2.5
func FromJSONReader(r io.Reader) (fyne.Theme, error) {
	var data jsonThemeData
	decoder := json.NewDecoder(r)
	if err := decoder.Decode(&data); err != nil {
		return DefaultTheme(), fmt.Errorf("error parsing JSON: %w", err)
	}

	theme := &jsonTheme{
		fallback: DefaultTheme(),
	}

	var err error

	// Parse generic colors
	theme.colors, err = parseColors(data.Colors)
	if err != nil {
		return DefaultTheme(), err
	}

	// Parse variant-specific colors
	theme.colorsDark, err = parseColors(data.ColorsDark)
	if err != nil {
		return DefaultTheme(), err
	}

	theme.colorsLight, err = parseColors(data.ColorsLight)
	if err != nil {
		return DefaultTheme(), err
	}

	// Parse sizes
	if data.Sizes != nil {
		theme.sizes = make(map[fyne.ThemeSizeName]float32)
		for name, size := range data.Sizes {
			theme.sizes[fyne.ThemeSizeName(name)] = size
		}
	}

	// Parse fonts
	theme.fonts, err = parseFonts(data.Fonts)
	if err != nil {
		return DefaultTheme(), err
	}

	// Parse icons
	theme.icons, err = parseIcons(data.Icons)
	if err != nil {
		return DefaultTheme(), err
	}

	return theme, nil
}

