package binding

import (
	"fmt"
	"sync"
)

// sprintfBinding is a String binding that formats multiple source bindings using a format string
type sprintfBinding struct {
	base
	format  string
	sources []DataItem
	lock    sync.RWMutex
}

// NewSprintf creates a new String binding that formats the values from multiple source bindings
// using fmt.Sprintf. The format string should contain format verbs matching the source types.
// Any changes to source bindings will trigger updates to this formatted binding.
//
// Example:
//   name := binding.NewString()
//   age := binding.NewInt()
//   formatted := binding.NewSprintf("Name: %s, Age: %d", name, age)
//
// Since: 2.5
func NewSprintf(format string, sources ...DataItem) String {
	if len(sources) == 0 {
		// Return a static string binding if no sources
		s := NewString()
		s.Set(format)
		return s
	}

	b := &sprintfBinding{
		format:  format,
		sources: sources,
	}

	// Listen to all source bindings for changes
	for _, source := range sources {
		source.AddListener(NewDataListener(func() {
			b.DataChanged()
		}))
	}

	return b
}

func (b *sprintfBinding) Get() (string, error) {
	b.lock.RLock()
	defer b.lock.RUnlock()

	if len(b.sources) == 0 {
		return b.format, nil
	}

	// Collect all values from source bindings
	values := make([]interface{}, len(b.sources))
	for i, source := range b.sources {
		var val interface{}
		var err error

		switch s := source.(type) {
		case String:
			val, err = s.Get()
		case Int:
			val, err = s.Get()
		case Float:
			val, err = s.Get()
		case Bool:
			val, err = s.Get()
		default:
			// For other types, try to get the underlying value through reflection
			// This is a simple fallback - specific type support can be added as needed
			val = fmt.Sprintf("%v", source)
		}

		if err != nil {
			return "", err
		}
		values[i] = val
	}

	return fmt.Sprintf(b.format, values...), nil
}

func (b *sprintfBinding) Set(s string) error {
	// sprintf bindings are read-only - they derive their value from sources
	return fmt.Errorf("cannot set value on sprintf binding - it is computed from source bindings")
}

func (b *sprintfBinding) AddListener(listener DataListener) {
	b.lock.Lock()
	defer b.lock.Unlock()

	b.listeners = append(b.listeners, listener)
}

func (b *sprintfBinding) RemoveListener(listener DataListener) {
	b.lock.Lock()
	defer b.lock.Unlock()

	for i, l := range b.listeners {
		if l == listener {
			b.listeners = append(b.listeners[:i], b.listeners[i+1:]...)
			break
		}
	}
}

func (b *sprintfBinding) DataChanged() {
	b.lock.RLock()
	listeners := make([]DataListener, len(b.listeners))
	copy(listeners, b.listeners)
	b.lock.RUnlock()

	for _, listener := range listeners {
		listener.DataChanged()
	}
}

