// Package validation provides validation for data inside widgets
package validation

import (
	"errors"
	"fmt"

	"fyne.io/fyne/v2"
)

// NewAllStrings creates a new validator that ensures the input matches one of the provided valid strings.
// The validator will return nil if the input matches any of the valid strings (case-sensitive),
// otherwise returns an error.
//
// Since: 2.5
func NewAllStrings(validStrings []string, reason string) fyne.StringValidator {
	if len(validStrings) == 0 {
		return func(text string) error {
			if reason != "" {
				return errors.New(reason)
			}
			return errors.New("no valid strings provided")
		}
	}

	// Create a map for efficient lookup
	validMap := make(map[string]bool, len(validStrings))
	for _, s := range validStrings {
		validMap[s] = true
	}

	return func(text string) error {
		if validMap[text] {
			return nil
		}

		if reason != "" {
			return errors.New(reason)
		}
		return fmt.Errorf("input must be one of: %v", validStrings)
	}
}

