package desktop

import "fyne.io/fyne/v2"

// App represents a desktop application with system tray integration capabilities.
// This extends the base fyne.App interface with methods for managing system tray.
//
// Since: 2.5
type App interface {
	fyne.App

	// SetSystemTrayMenu sets the menu to be displayed when the system tray icon is interacted with.
	// The menu parameter can be nil to remove the system tray menu.
	SetSystemTrayMenu(menu *fyne.Menu)

	// SetSystemTrayIcon sets the icon to be displayed in the system tray.
	// The icon parameter represents the resource to display in the system tray.
	SetSystemTrayIcon(icon fyne.Resource)
}

